"""Tests for the bulk discount module."""

from decimal import Decimal

import pytest

from pricing import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    LineItem,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


class TestQualifiesForBulkDiscount:
    """Tests for qualifies_for_bulk_discount function."""

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify(self) -> None:
        item = LineItem("sku", Decimal("10.00"), quantity=9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-8764baca")
    def test_quantity_10_qualifies(self) -> None:
        item = LineItem("sku", Decimal("10.00"), quantity=10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_11_qualifies(self) -> None:
        item = LineItem("sku", Decimal("10.00"), quantity=11)
        assert qualifies_for_bulk_discount(item) is True


class TestCalculateBulkDiscount:
    """Tests for calculate_bulk_discount function."""

    @pytest.mark.l4("C-1caf4da3")
    def test_quantity_9_returns_zero_discount(self) -> None:
        item = LineItem("sku", Decimal("10.00"), quantity=9)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-8764baca")
    def test_quantity_10_applies_5_percent_discount(self) -> None:
        item = LineItem("sku", Decimal("10.00"), quantity=10)
        expected_discount = (Decimal("10.00") * 10 * Decimal("5")) / Decimal("100")
        assert calculate_bulk_discount(item) == expected_discount

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_10_applies_5_percent_discount(self) -> None:
        item = LineItem("sku", Decimal("10.00"), quantity=20)
        expected_discount = (Decimal("10.00") * 20 * Decimal("5")) / Decimal("100")
        assert calculate_bulk_discount(item) == expected_discount

    @pytest.mark.l4("C-1caf4da3")
    def test_non_qualifying_item_returns_zero(self) -> None:
        item = LineItem("sku", Decimal("100.00"), quantity=5)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding(self) -> None:
        # 100 * 10 * 0.05 = 50.00 (no rounding needed)
        item = LineItem("sku", Decimal("100.00"), quantity=10)
        assert calculate_bulk_discount(item) == Decimal("50.00")

